{
  "findings": [
    {
      "check_id": "CKV_AZURE_15",
      "title": "Key Vault key size is too small",
      "resource": "azurerm_key_vault_key.generated",
      "severity": "HIGH",
      "explanation": "The key size of 2048 bits is considered less secure for RSA keys. A key size of at least 3072 bits is recommended for stronger encryption and to meet modern security standards."
    }
  ],
  "patched_code": "resource "azurerm_key_vault_key" "generated" {
  name         = "terragoat-generated-certificate-${var.environment}"
  key_vault_id = azurerm_key_vault.example.id
  key_type     = "RSA"
  key_size     = 3072
  key_opts = [
    "decrypt",
    "encrypt",
    "sign",
    "unwrapKey",
    "verify",
    "wrapKey",
  ]
}",
  "fix_summary": "Increased the RSA key size from 2048 bits to 3072 bits to enhance encryption strength and align with modern security standards."
}
